@dataclass(frozen=True)
class MetricSpec:
    name: str
    formula: str
    window: str
    source: str


@dataclass(frozen=True)
class EscalationSpec:
    condition: str
    owner: str
    action: str


@dataclass(frozen=True)
class RoleSpec:
    name: str
    decision: str
    inputs: tuple[str, ...]
    outputs: tuple[str, ...]
    workflow: tuple[str, ...]
    metrics: tuple[MetricSpec, ...]
    scope: str
    secondary_decision: str
    knowledge: tuple[str, ...]
    data_objects: tuple[str, ...]
    tools: tuple[tuple[str, str], ...]
    skills: tuple[str, ...]
    capabilities: tuple[str, ...]
    rhythm: tuple[str, str, str]
    escalations: tuple[EscalationSpec, EscalationSpec]
    learning: tuple[str, ...]
    score: tuple[int, int, int, int]
    cadence: str
    rationale: str


@dataclass(frozen=True)
class IndustrySpec:
    key: str
    start: int
    tagline: str
    groups: tuple[tuple[str, str, str, str], ...]
    pains: tuple[dict, ...]
    roles: tuple[RoleSpec, ...]


def _parts(value: str, separator: str = "；") -> tuple[str, ...]:
    return tuple(item.strip() for item in value.split(separator) if item.strip())


def _metric(value: str) -> MetricSpec:
    parts = tuple(item.strip() for item in value.split("~"))
    if len(parts) != 4:
        raise ValueError(f"metric needs name/formula/window/source: {value}")
    return MetricSpec(*parts)


def _escalation(value: str) -> EscalationSpec:
    parts = tuple(item.strip() for item in value.split("~"))
    if len(parts) != 3:
        raise ValueError(f"escalation needs condition/owner/action: {value}")
    return EscalationSpec(*parts)


def parse_roles(block: str) -> tuple[RoleSpec, ...]:
    roles = []
    for line_no, raw in enumerate(block.strip().splitlines(), 1):
        if not raw.strip():
            continue
        fields = tuple(item.strip() for item in raw.split("|"))
        # A 21-column row intentionally declares one five-step procedural
        # vector as both the role's executable workflow and its skill tree.
        # Those steps still live in the individual RoleSpec row; this is not a
        # category template.  A 22-column row may keep the two vectors apart.
        if len(fields) == 21:
            fields = (*fields[:4], fields[12], *fields[4:])
        if len(fields) != 22:
            raise ValueError(f"RoleSpec line {line_no} has {len(fields)} fields, expected 21 or 22")
        (
            name, decision, inputs, outputs, workflow, metric1, metric2,
            metric3, scope, secondary, knowledge, objects, tools, skills,
            capabilities, rhythm, hold, escalate, learning, score, cadence,
            rationale,
        ) = fields
        parsed_tools = []
        for item in _parts(tools):
            tool, marker, tool_scope = item.partition("@")
            if not marker or not tool.strip() or not tool_scope.strip():
                raise ValueError(f"{name}: malformed tool {item}")
            parsed_tools.append((tool.strip(), tool_scope.strip()))
        score_values = tuple(int(item) for item in score.split(","))
        role = RoleSpec(
            name=name,
            decision=decision,
            inputs=_parts(inputs),
            outputs=_parts(outputs),
            workflow=_parts(workflow),
            metrics=(_metric(metric1), _metric(metric2), _metric(metric3)),
            scope=scope,
            secondary_decision=secondary,
            knowledge=_parts(knowledge),
            data_objects=_parts(objects),
            tools=tuple(parsed_tools),
            skills=_parts(skills),
            capabilities=_parts(capabilities),
            rhythm=tuple(_parts(rhythm)),
            escalations=(_escalation(hold), _escalation(escalate)),
            learning=_parts(learning),
            score=score_values,
            cadence=cadence,
            rationale=rationale,
        )
        roles.append(role)
    return tuple(roles)


