def _canon(value: object, employee: dict, *, deep: bool = False) -> str:
    text = value if isinstance(value, str) else json.dumps(
        value, ensure_ascii=False, sort_keys=True,
    )
    contract = employee["decision_contract"]
    profile = employee["professional_profile"]
    tokens: set[str] = {
        str(employee.get(field) or "") for field in (
            "name", "person", "key", "role", "duty", "desc", "intro",
            "group", "idx", "num", "primary_decision",
        )
    }
    if deep:
        tokens.update(contract["required_inputs"])
        tokens.update(contract["outputs"])
        tokens.update(profile["data_objects"])
        tokens.update(metric["name"] for metric in contract["success_metrics"])
    for token in sorted((token for token in tokens if token), key=len, reverse=True):
        text = text.replace(token, "§")
    text = re.sub(r"\d+|GO|HOLD|ESCALATE|ADVISE|分母为0(?:时)?记N/A", "", text, flags=re.I)
    return re.sub(r"[^\w\u4e00-\u9fff§]+", "", text).lower()


def _similarity(values: list[str]) -> tuple[float, tuple[int, int] | None]:
    best = 0.0
    pair = None
    for left in range(len(values)):
        for right in range(left + 1, len(values)):
            ratio = SequenceMatcher(None, values[left], values[right], autojunk=False).ratio()
            if ratio > best:
                best, pair = ratio, (left, right)
    return best, pair


def _quality_audit(industry: str, employees: list[dict]) -> dict:
    getters = {
        "workflow": lambda e: e["decision_contract"]["workflow"],
        "outputs": lambda e: e["decision_contract"]["outputs"],
        "metrics": lambda e: [
            {key: metric[key] for key in ("name", "formula", "window", "source")}
            for metric in e["decision_contract"]["success_metrics"]
        ],
        "selection_rationale": lambda e: e["selection_rationale"],
        "scope": lambda e: e["professional_profile"]["scope"],
        "decisions": lambda e: e["professional_profile"]["decisions"],
        "knowledge": lambda e: e["professional_profile"]["knowledge_domains"],
        "objects": lambda e: e["professional_profile"]["data_objects"],
        "tools": lambda e: e["professional_profile"]["tool_permissions"],
        "skills": lambda e: e["professional_profile"]["skill_tree"],
        "capabilities": lambda e: e["professional_profile"]["capabilities"],
        "rhythm": lambda e: e["professional_profile"]["operating_rhythm"],
        "escalation": lambda e: e["professional_profile"]["escalation_matrix"],
        "learning": lambda e: e["professional_profile"]["learning_tracks"],
    }
    result = {}
    for field, getter in getters.items():
        values = [_canon(getter(employee), employee) for employee in employees]
        if len(values) != len(set(values)):
            raise ValueError(f"{industry}/{field}: duplicate role substance")
        maximum, pair = _similarity(values)
        if maximum >= 0.86:
            assert pair is not None
            raise ValueError(
                f"{industry}/{field}: {employees[pair[0]]['idx']} vs "
                f"{employees[pair[1]]['idx']} similarity={maximum:.4f}"
            )
        result[field] = {"unique": len(set(values)), "max_similarity": round(maximum, 4)}

    # KPI-specific anti-template gate required by schema54: after stripping
    # identity, all required inputs, output names and data-object nouns, the
    # complete three-KPI algorithm/window/source-ledger structure must remain
    # exact-unique and below the same semantic-copy threshold.
    kpi_shapes = [
        _canon(
            [
                {key: metric[key] for key in ("name", "formula", "window", "source")}
                for metric in employee["decision_contract"]["success_metrics"]
            ],
            employee,
            deep=True,
        )
        for employee in employees
    ]
    if len(kpi_shapes) != len(set(kpi_shapes)):
        raise ValueError(f"{industry}/kpi_stripped_structure: exact template duplicate")
    maximum, pair = _similarity(kpi_shapes)
    if maximum >= 0.86:
        assert pair is not None
        raise ValueError(
            f"{industry}/kpi_stripped_structure: {employees[pair[0]]['idx']} vs "
            f"{employees[pair[1]]['idx']} similarity={maximum:.4f}"
        )
    result["kpi_stripped_structure"] = {
        "unique": len(set(kpi_shapes)), "max_similarity": round(maximum, 4),
    }
    return result


def _validate_roles(spec: IndustrySpec) -> None:
    if len(spec.roles) != 36:
        raise ValueError(f"{spec.key}: needs 36 RoleSpecs, got {len(spec.roles)}")
    if len(spec.groups) != 8 or len(spec.pains) != 8:
        raise ValueError(f"{spec.key}: needs eight groups and eight pain clusters")
    names = [role.name for role in spec.roles]
    decisions = [role.decision for role in spec.roles]
    if len(set(names)) != 36 or len(set(decisions)) != 36:
        raise ValueError(f"{spec.key}: role names and decisions must be unique")
    for role in spec.roles:
        checks = (
            (len(role.inputs) == 4, "four inputs"),
            (len(role.outputs) == 2, "two outputs"),
            (len(role.workflow) >= 4, "four workflow steps"),
            (len(role.metrics) == 3, "three explicit KPIs"),
            (len(role.knowledge) >= 3, "three knowledge domains"),
            (len(role.data_objects) >= 3, "three data objects"),
            (len(role.tools) >= 2, "two read-only systems"),
            (len(role.skills) >= 5, "five skills"),
            (len(role.capabilities) >= 4, "four capabilities"),
            (len(role.rhythm) == 3, "three operating rhythms"),
            (len(role.escalations) == 2, "two escalations"),
            (len(role.learning) >= 3, "three learning tracks"),
            (len(role.score) == 4 and all(1 <= value <= 5 for value in role.score), "valid score"),
        )
        for ok, message in checks:
            if not ok:
                raise ValueError(f"{spec.key}/{role.name}: needs {message}")
        for metric in role.metrics:
            if not metric.name or not metric.formula or not metric.window or not metric.source:
                raise ValueError(f"{spec.key}/{role.name}: KPI fields cannot be empty")
            if not any(operator in metric.formula for operator in (
                "÷", "−", "+", "中位数", "合计", "次数", "数量", "时长", "数",
            )):
                raise ValueError(f"{spec.key}/{role.name}: KPI has no computable algorithm")


def build_catalog(spec: IndustrySpec) -> dict:
    _validate_roles(spec)
    base = json.loads((V2_DIR / f"{spec.key}.json").read_text(encoding="utf-8"))
    v1 = json.loads((V1_DIR / f"{spec.key}.json").read_text(encoding="utf-8"))
    people = {int(employee["idx"]): str(employee["person"]) for employee in v1["employees"]}
    sources = [*base["sources"], *EXTRA_SOURCES.get(spec.key, ())]
    source_ids = [str(source.get("id") or "") for source in sources]
    if not all(source_ids) or len(source_ids) != len(set(source_ids)):
        raise ValueError(f"{spec.key}: source ids must be non-empty and unique")
    known_sources = set(source_ids)
    for pain in spec.pains:
        bound_sources = set(pain.get("source_ids") or ())
        if not bound_sources or not bound_sources <= known_sources:
            raise ValueError(
                f"{spec.key}/{pain.get('code')}: source_ids must resolve exactly"
            )
    if spec.key == "beauty":
        privacy_pain = next(
            pain for pain in spec.pains
            if pain["code"] == "BEAUTYV3-PRIVACY-FINANCE-CONTINUITY"
        )
        if "beauty-pipl-2021" not in privacy_pain["source_ids"]:
            raise ValueError("beauty: sensitive-image privacy pain must bind PIPL")
    if spec.key == "pet":
        welfare_pain = next(
            pain for pain in spec.pains
            if pain["code"] == "PETV3-WELFARE-DATA-CONTINUITY"
        )
        if not {
            "pet-welfare-woah-2021", "pet-premises-cleaning-2025",
        } <= set(welfare_pain["source_ids"]):
            raise ValueError("pet: animal-welfare pain lacks welfare/premises sources")
    employees = []
    groups = []
    cursor = 0
    for group_index, (group_name, emoji, color, pain_code) in enumerate(spec.groups):
        members = []
        for _ in range(GROUP_SIZES[group_index]):
            idx = spec.start + cursor
            employees.append(_employee(spec, spec.roles[cursor], idx, people[idx], spec.groups[group_index]))
            members.append(idx)
            cursor += 1
        groups.append({"name": group_name, "emoji": emoji, "color": color, "members": members})
    ranked = sorted(
        employees,
        key=lambda employee: (
            -employee["priority_score"]["total"],
            -employee["priority_score"]["usage_frequency"],
            -employee["priority_score"]["economic_value"],
            -employee["priority_score"]["pain_severity"],
            -employee["priority_score"]["data_availability"],
            employee["idx"],
        ),
    )
    for rank, employee in enumerate(ranked, 1):
        employee["priority_rank"] = rank
    quality = _quality_audit(spec.key, employees)
    return {
        "key": spec.key,
        "name": base["name"],
        "emoji": base["emoji"],
        "tagline": spec.tagline,
        "catalog_version": CATALOG_VERSION,
        "as_of": AS_OF,
        "identity_policy": "保留V1原始idx与person；V3是同一在岗员工的当前岗位版本，旧任务继续冻结其历史岗位版本。",
        "selection_policy": "按痛点严重度、使用频率、经济价值和企业数据可得性逐岗评分；36岗均有独立决策、流程、工具、KPI与升级边界。",
        "sources": sources,
        "pain_points": list(spec.pains),
        "groups": groups,
        "employees": employees,
        "quality_audit": {
            "method": "剥离员工身份后对14个职责字段做精确指纹与SequenceMatcher；三KPI另剥离输入对象与产物后复审算法/窗口/源账结构。",
            **quality,
        },
    }


def _payload(catalog: dict) -> str:
    return json.dumps(catalog, ensure_ascii=False, indent=2) + "\n"


def _validate_global_metrics(catalogs: dict[str, dict]) -> dict:
    """Reject KPI collisions and a shared three-KPI skeleton across catalogs."""
    employees = [
        employee
        for catalog in catalogs.values()
        for employee in catalog["employees"]
    ]
    metrics = [
        metric
        for employee in employees
        for metric in employee["decision_contract"]["success_metrics"]
    ]
    if len(metrics) != len(employees) * 3:
        raise ValueError("global: every employee must have exactly three KPIs")
    unique_counts = {}
    for field in ("key", "name", "formula"):
        values = [metric[field] for metric in metrics]
        unique_counts[field] = len(set(values))
        if unique_counts[field] != len(values):
            duplicates = sorted({value for value in values if values.count(value) > 1})
            raise ValueError(
                f"global/metric_{field}: exact collision: {duplicates[:3]}"
            )
    for employee in employees:
        subject = employee["name"][:-1] if employee["name"].endswith("官") else employee["name"]
        if not all(
            metric["name"].startswith(f"{subject}·")
            for metric in employee["decision_contract"]["success_metrics"]
        ):
            raise ValueError(
                f"global/metric_name: {employee['idx']} lacks its business subject"
            )

    stripped_shapes = [
        _canon(
            [
                {key: metric[key] for key in ("name", "formula", "window", "source")}
                for metric in employee["decision_contract"]["success_metrics"]
            ],
            employee,
            deep=True,
        )
        for employee in employees
    ]
    if len(stripped_shapes) != len(set(stripped_shapes)):
        raise ValueError("global/kpi_stripped_structure: exact template duplicate")
    maximum, pair = _similarity(stripped_shapes)
    if maximum >= 0.86:
        assert pair is not None
        raise ValueError(
            f"global/kpi_stripped_structure: {employees[pair[0]]['idx']} vs "
            f"{employees[pair[1]]['idx']} similarity={maximum:.4f}"
        )
    return {
        "employees": len(employees),
        "metrics": len(metrics),
        "unique": unique_counts,
        "stripped_unique": len(set(stripped_shapes)),
        "stripped_max_similarity": round(maximum, 4),
    }


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--industry", choices=(*INDUSTRIES, "all"), default="all")
    parser.add_argument("--check", action="store_true", help="verify checked-in JSON byte-for-byte")
    args = parser.parse_args()
    selected: Iterable[str] = INDUSTRIES if args.industry == "all" else (args.industry,)
    catalogs = {key: build_catalog(INDUSTRIES[key]) for key in selected}
    global_metrics = _validate_global_metrics(catalogs)
    if args.industry == "all" and (
        global_metrics["employees"] != 108 or global_metrics["metrics"] != 324
    ):
        raise ValueError("global: all must contain 108 employees and 324 KPIs")
    if not args.check:
        OUT_DIR.mkdir(parents=True, exist_ok=True)
    for key, catalog in catalogs.items():
        payload = _payload(catalog)
        path = OUT_DIR / f"{key}.json"
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != payload:
                raise SystemExit(f"OUT-OF-DATE {path}")
        else:
            path.write_text(payload, encoding="utf-8")
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        kpi = catalog["quality_audit"]["kpi_stripped_structure"]
        print(
            f"{key}: employees=36 pains=8 kpi_unique={kpi['unique']} "
            f"kpi_max={kpi['max_similarity']:.4f} sha256={digest}"
        )
    print(
        "global: "
        f"employees={global_metrics['employees']} metrics={global_metrics['metrics']} "
        f"key/name/formula_unique={global_metrics['unique']['key']}/"
        f"{global_metrics['unique']['name']}/{global_metrics['unique']['formula']} "
        f"stripped_unique={global_metrics['stripped_unique']} "
        f"stripped_max={global_metrics['stripped_max_similarity']:.4f}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
